#include "cryptoutils.h"
int main(void){unsigned long long n,e,c;printf("Enter public exponent e and modulus n: ");if(scanf("%llu %llu",&e,&n)!=2||n<27)return 1;printf("Enter one ciphertext integer c: ");if(scanf("%llu",&c)!=1)return 1;printf("Brute-force the 26 possible letters (A=0,...,Z=25):\n");int hits=0;for(int m=0;m<26;m++)if(cu_modpow((unsigned long long)m,e,n)==c){printf("c matches plaintext letter %c (m=%d)\n",'A'+m,m);hits++;}if(!hits)puts("No single-letter match; ciphertext might encode a different block or use padding/randomization.");puts("Raw RSA per character is deterministic and leaks patterns; encrypt properly padded blocks (e.g. RSA-OAEP), not each character separately.");return 0;}
